<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Bilingual Counter / 双语计数器</title>
<style>
  :root { color-scheme: light; font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }
  * { box-sizing: border-box; }
  body { margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center; background: #f6f7fb; color: #1a1a1a; padding: 24px; }
  main { width: 100%; max-width: 480px; text-align: center; background: #fff; border-radius: 16px; padding: 32px 24px; box-shadow: 0 8px 24px rgba(0,0,0,0.08); }
  h1 { font-size: clamp(1.5rem, 4vw, 2rem); margin: 0 0 8px; }
  p.subtitle { margin: 0 0 24px; color: #555; font-size: 0.95rem; }
  .counter { font-size: clamp(3rem, 10vw, 4.5rem); font-weight: 700; line-height: 1.1; margin: 0 0 12px; letter-spacing: -0.02em; }
  .empty-hint { margin: 0 0 24px; color: #777; font-size: 0.9rem; min-height: 1.4em; }
  .actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
  button { appearance: none; border: none; cursor: pointer; font-size: 1rem; padding: 12px 24px; border-radius: 999px; font-weight: 600; transition: transform 0.1s ease, box-shadow 0.1s ease, background 0.2s ease; }
  button:focus-visible { outline: 3px solid #4d90fe; outline-offset: 2px; }
  button:active { transform: translateY(1px); }
  .btn-add { background: #2563eb; color: #fff; box-shadow: 0 4px 12px rgba(37,99,235,0.3); }
  .btn-add:hover { background: #1d4ed8; }
  .btn-reset { background: #e5e7eb; color: #1f2937; }
  .btn-reset:hover { background: #d1d5db; }
  @media (max-width: 480px) {
    main { padding: 28px 20px; border-radius: 12px; }
    button { padding: 14px 20px; font-size: 1.05rem; flex: 1 1 auto; }
  }
</style>
</head>
<body>
<main id="app" role="main" aria-label="Bilingual Counter / 双语计数器">
  <h1>Bilingual Counter<br><span lang="zh-CN">双语计数器</span></h1>
  <p class="subtitle">Offline self-contained demo · 离线自包含演示</p>
  <div class="counter" id="countDisplay" aria-live="polite" aria-atomic="true">0</div>
  <p class="empty-hint" id="emptyHint">Initial state: count is zero.<br><span lang="zh-CN">初始状态：计数为零。</span></p>
  <div class="actions">
    <button type="button" id="addBtn" class="btn-add" aria-label="Add one / 加一">Add / 加一</button>
    <button type="button" id="resetBtn" class="btn-reset" aria-label="Reset to zero / 清零">Reset / 清零</button>
  </div>
</main>
<script>
(function () {
  var count = 0;
  var display = document.getElementById('countDisplay');
  var hint = document.getElementById('emptyHint');
  var addBtn = document.getElementById('addBtn');
  var resetBtn = document.getElementById('resetBtn');

  function render() {
    display.textContent = String(count);
    if (count === 0) {
      hint.innerHTML = 'Initial state: count is zero.<br><span lang="zh-CN">初始状态：计数为零。</span>';
    } else {
      hint.innerHTML = 'Current total: ' + count + '<br><span lang="zh-CN">当前总计：' + count + '</span>';
    }
  }

  addBtn.addEventListener('click', function () {
    count += 1;
    render();
  });

  resetBtn.addEventListener('click', function () {
    count = 0;
    render();
  });

  render();
})();
</script>
</body>
</html>
HTMLEOF
echo "wrote index.html"

